import {clearRetainedInput} from './inline-drafts.js';
import { el,button,field,modal,busy,notify,dateText } from './utils.js';
import { api } from './service.js';
const ROLES=['viewer','operator','approver','admin'];const name=member=>member.email||member.name||member.externalRef||member.id;
const inlineError=()=>el('p',{class:'banner error',role:'alert',hidden:'',tabindex:'-1'});
const reasonField=()=>el('textarea',{class:'field-control',name:'reason',rows:3,maxlength:500,required:'',autocomplete:'off'});
function submit(control,error,task){return busy(control,async()=>{error.hidden=true;try{await task();}catch(problem){error.hidden=false;error.textContent=problem.message;error.focus();}});}
function confirmation(title,description,action,done){const m=modal(title,description,true);const reason=reasonField();const error=inlineError();m.content.append(field('Reason for this change',reason),error);const confirm=button('Confirm '+title.toLowerCase(),()=>submit(confirm,error,async()=>{if(!reason.value.trim()){reason.focus();throw new Error('Enter a reason before confirming.');}await action(reason.value.trim());m.close();await done();}),'danger');m.bottom.append(button('Keep access unchanged',m.close),confirm);return m;}
function editRoles(member,data,refresh){const m=modal('Edit workspace roles',`Change access for ${name(member)}. The server protects your own access and the last administrator.`,true);const selected=new Set(member.roles||[]);const choices=el('fieldset',{class:'stack'},el('legend',{class:'field-label',text:'Workspace roles'}));for(const role of ROLES){const input=el('input',{type:'checkbox',name:'memberRole',value:role,checked:selected.has(role)});input.addEventListener('change',()=>input.checked?selected.add(role):selected.delete(role));choices.append(el('label',{class:'account-choice'},input,el('span',{text:role[0].toUpperCase()+role.slice(1)})));}const reason=reasonField();const error=inlineError();m.content.append(choices,el('p',{class:'field-help',text:'Each role includes permissions below it. Use Remove access to revoke workspace membership.'}),field('Reason for role change',reason),error);const save=button('Save workspace roles',()=>submit(save,error,async()=>{if(!selected.size)throw new Error('Select a role, or use Remove access from the roster.');if(!reason.value.trim()){reason.focus();throw new Error('Enter a reason before changing roles.');}await api('team-member-save',{principalId:member.id,roles:ROLES.filter(role=>selected.has(role)),reason:reason.value.trim()});m.close();await refresh();notify('Workspace roles updated.');}),'primary');m.bottom.append(button('Cancel',m.close),save);return m;}
function inviteForm(refresh){const form=el('section',{class:'info-card'},el('h3',{text:'Invite by email'}),el('p',{class:'field-help',text:'Invitations grant access after the invited Google identity signs in. Recording an invitation does not send an email.'}));const email=el('input',{class:'field-control',type:'email',name:'inviteEmail','data-retain-input':'true',required:'',autocomplete:'email',placeholder:'teammate@example.com…',spellcheck:'false'});const role=el('select',{class:'field-control',name:'inviteRole','data-retain-input':'true'},...ROLES.map(value=>el('option',{value,text:value[0].toUpperCase()+value.slice(1)})));const error=inlineError();const invite=button('Invite teammate',()=>submit(invite,error,async()=>{if(!email.validity.valid||!email.value.trim()){email.reportValidity();return;}await api('team-invite',{email:email.value.trim(),roles:[role.value]});email.value='';clearRetainedInput(email);await refresh();notify('Invitation recorded. Share the workspace sign-in link with your teammate.');}),'primary');form.append(field('Teammate email',email),field('Workspace role',role),error,invite);return form;}
export function renderTeam(data,refresh){const admin=data.roles?.includes('admin');const members=data.members||[];const invitations=data.invitations||[];const admins=members.filter(member=>member.roles?.includes('admin'));const root=el('div',{class:'stack'});if(data.errors?.['team-list'])root.append(el('p',{class:'banner error',role:'alert',text:'Team access data could not refresh. Reopen this view before relying on its membership status.'}));const panel=el('section',{class:'content-panel'},el('div',{class:'panel-toolbar'},el('h2',{text:'Team & roles'}),el('span',{class:'muted',text:`${members.filter(member=>member.roles?.length).length.toLocaleString()} active members`})));const rows=el('tbody');
 for(const member of members){const controls=el('td');const roles=member.roles||[];const self=(data.principalId||data.currentPrincipalId)===member.id;const lastAdmin=roles.includes('admin')&&admins.length===1;if(admin){const edit=button(roles.length?'Edit roles':'Restore access',()=>editRoles(member,data,refresh),'small');edit.setAttribute('aria-label',`Edit roles for ${name(member)}`);controls.append(edit);if(roles.length){const remove=button('Remove access',()=>confirmation('Remove access',`Remove ${name(member)} from this workspace. Approved work may continue under its own authorizations; this revokes the teammate’s access.`,reason=>api('team-member-save',{principalId:member.id,roles:[],reason}),async()=>{await refresh();notify('Workspace access removed.');}),'small danger');remove.setAttribute('aria-label',`Remove access for ${name(member)}`);remove.disabled=self||lastAdmin;if(remove.disabled)remove.title=self?'You cannot remove your own access.':'Keep at least one administrator.';controls.append(remove);}}
  rows.append(el('tr',{},el('td',{},el('strong',{text:name(member)}),self?el('small',{class:'field-help',text:'You'}):null),el('td',{text:roles.length?roles.join(', '):'No workspace access'}),...(admin?[controls]:[])));}
 panel.append(el('div',{class:'table-scroll'},el('table',{class:'report-table'},el('thead',{},el('tr',{},el('th',{scope:'col',text:'Member'}),el('th',{scope:'col',text:'Roles'}),admin?el('th',{scope:'col',text:'Access controls'}):null)),rows)));if(!members.length)panel.append(el('p',{class:'inline-note',text:'No team roster was returned for this workspace.'}));if(!admin)panel.append(el('p',{class:'inline-note',text:'Only administrators can change membership and invitations.'}));root.append(panel);if(admin)root.append(inviteForm(refresh));
 const pending=el('section',{class:'info-card'},el('h3',{text:'Invitations'}));if(!invitations.length)pending.append(el('p',{class:'field-help',text:admin?'No invitations recorded.':'Invitation records are visible to administrators.'}));for(const invitation of invitations){const expires=invitation.expiresAt||invitation.expires_at;const status=invitation.status||(invitation.acceptedAt||invitation.accepted_at?'Accepted':expires&&expires<Date.now()?'Expired':'Pending');const row=el('article',{class:'review-tile'},el('strong',{text:invitation.email}),el('p',{class:'field-help',text:`${(invitation.roles||[]).join(', ')} · ${status}${expires?' · Expires '+dateText(expires):''}`}));if(admin&&status.toLowerCase()==='pending'){const revoke=button('Revoke invitation',()=>confirmation('Revoke invitation',`Cancel the pending invitation for ${invitation.email}. This does not remove an accepted member.`,reason=>api('team-invite-revoke',{invitationId:invitation.id,reason}),async()=>{await refresh();notify('Pending invitation revoked.');}),'small danger');revoke.setAttribute('aria-label',`Revoke invitation for ${invitation.email}`);row.append(revoke);}pending.append(row);}root.append(pending);return root;
}
